private static final int[] DR = {-2, -2, -1, -1, 1, 1, 2, 2};
private static final int[] DC = {-1, 1, -2, 2, -2, 2, -1, 1};
private int n;
private int[][] board;
private int tours;

public int countTours(int size, int sr, int sc) {
    n = size;
    board = new int[n][n];
    tours = 0;
    board[sr][sc] = 1; // first cell visited
    solve(sr, sc, 1);
    return tours;
}

private void solve(int r, int c, int count) {
    if (count == n * n) { tours++; return; } // full tour
    for (int d = 0; d < 8; d++) {
        int nr = r + DR[d], nc = c + DC[d];
        if (nr >= 0 && nr < n && nc >= 0 && nc < n && board[nr][nc] == 0) {
            board[nr][nc] = count + 1;   // choose
            solve(nr, nc, count + 1);
            board[nr][nc] = 0;           // un-choose (backtrack)
        }
    }
}

private static final int[] DR = {-2, -2, -1, -1, 1, 1, 2, 2};
private static final int[] DC = {-1, 1, -2, 2, -2, 2, -1, 1};
private int n;
private int[][] board;

public int[][] findTour(int size, int sr, int sc) {
    n = size;
    board = new int[n][n];
    board[sr][sc] = 1;
    if (solve(sr, sc, 1)) return board;
    return null; // no tour found
}

private int degree(int r, int c) {
    int cnt = 0;
    for (int d = 0; d < 8; d++) {
        int nr = r + DR[d], nc = c + DC[d];
        if (nr >= 0 && nr < n && nc >= 0 && nc < n && board[nr][nc] == 0) cnt++;
    }
    return cnt;
}

private boolean solve(int r, int c, int count) {
    if (count == n * n) return true;
    // collect legal moves with their onward degree
    List<int[]> moves = new ArrayList<>();
    for (int d = 0; d < 8; d++) {
        int nr = r + DR[d], nc = c + DC[d];
        if (nr >= 0 && nr < n && nc >= 0 && nc < n && board[nr][nc] == 0) {
            moves.add(new int[]{degree(nr, nc), nr, nc});
        }
    }
    moves.sort((a, b) -> Integer.compare(a[0], b[0])); // Warnsdorff: fewest first
    for (int[] m : moves) {
        int nr = m[1], nc = m[2];
        board[nr][nc] = count + 1;       // choose
        if (solve(nr, nc, count + 1)) return true;
        board[nr][nc] = 0;               // un-choose (fallback)
    }
    return false;
}

