DR = (-2, -2, -1, -1, 1, 1, 2, 2)
DC = (-1, 1, -2, 2, -2, 2, -1, 1)

def findTour(self, size: int, sr: int, sc: int):
    n = size
    board = [[0] * n for _ in range(n)]
    board[sr][sc] = 1

    def degree(r: int, c: int) -> int:
        cnt = 0
        for dr, dc in zip(DR, DC):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and board[nr][nc] == 0:
                cnt += 1
        return cnt

    def solve(r: int, c: int, count: int) -> bool:
        if count == n * n:
            return True
        moves = []
        for dr, dc in zip(DR, DC):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and board[nr][nc] == 0:
                moves.append((degree(nr, nc), nr, nc))
        moves.sort()  # Warnsdorff: fewest onward moves first
        for _, nr, nc in moves:
            board[nr][nc] = count + 1   # choose
            if solve(nr, nc, count + 1):
                return True
            board[nr][nc] = 0           # un-choose (fallback)
        return False

    return board if solve(sr, sc, 1) else None

